END, "updatedAt" = now() WHERE slug = $xw$chatgpt$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%Accounting plugin helps reconcile transactions%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-19): Gemini 4 Neon (gemini-4-neon), introduced 2026-11-18, is priced at $3 per 1M input tokens and $15 per 1M output tokens, with a 1 million-token context window. Context caching is $0.15 per 1M tokens, and the pricing page says implicit caching only. The pricing page says Neon is not available on the free tier, and that every token is billed, including thinking tokens. The launch post says developers can build with the paid Gemini API tier in Google AI Studio and Android Studio, that paid Google AI Pro and Ultra subscribers can try Neon in Google Antigravity, and that Pro and Ultra subscribers can try it in AI Studio. It also says enterprises can use it in Gemini for business, by the API or the model menu, and in Google Antigravity, and that Google AI Pro and Ultra subscribers can select it in the Gemini app.$xw$
  ELSE description || $xw$ Note (2026-11-19): Gemini 4 Neon (gemini-4-neon), introduced 2026-11-18, is priced at $3 per 1M input tokens and $15 per 1M output tokens, with a 1 million-token context window. Context caching is $0.15 per 1M tokens, and the pricing page says implicit caching only. The pricing page says Neon is not available on the free tier, and that every token is billed, including thinking tokens. The launch post says developers can build with the paid Gemini API tier in Google AI Studio and Android Studio, that paid Google AI Pro and Ultra subscribers can try Neon in Google Antigravity, and that Pro and Ultra subscribers can try it in AI Studio. It also says enterprises can use it in Gemini for business, by the API or the model menu, and in Google Antigravity, and that Google AI Pro and Ultra subscribers can select it in the Gemini app.$xw$
END, "updatedAt" = now() WHERE slug = $xw$gemini$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%Gemini 4 Neon (gemini-4-neon)%$xw$;

